void suggest_default_idmap(void)
{
FILE *f;
unsigned int uid = 0, urange = 0, gid = 0, grange = 0;
char *line = NULL;
char *uname, *gname;
size_t len = 0;
if (!(uname = getuname()))
return;
if (!(gname = getgname())) {
free(uname);
return;
}
f = fopen(subuidfile, "r");
if (!f) {
ERROR("Your system is not configured with subuids");
free(gname);
free(uname);
return;
}
while (getline(&line, &len, f) != -1) {
char *p = strchr(line, ':'), *p2;
if (*line == '#')
continue;
if (!p)
continue;
*p = '\0';
p++;
if (strcmp(line, uname))
continue;
p2 = strchr(p, ':');
if (!p2)
continue;
*p2 = '\0';
p2++;
if (!*p2)
continue;
uid = atoi(p);
urange = atoi(p2);
}
fclose(f);
f = fopen(subuidfile, "r");
if (!f) {
ERROR("Your system is not configured with subgids");
free(gname);
free(uname);
return;
}
while (getline(&line, &len, f) != -1) {
char *p = strchr(line, ':'), *p2;
