} else {
_LOGW (LOGD_HW, "failed to look up interface index");
}
}
g_hash_table_remove_all (priv->ip6_saved_properties);
if (g_strcmp0 (old_ip_iface, priv->ip_iface))
g_object_notify (G_OBJECT (self), NM_DEVICE_IP_IFACE);
g_free (old_ip_iface);
}
