TIFFGetField (tif, TIFFTAG_IMAGELENGTH, &im_height) == 0 ||
TIFFGetField (tif, TIFFTAG_TILEWIDTH, &tile_width) ==  0 ||
TIFFGetField (tif, TIFFTAG_TILELENGTH, &tile_height) == 0) {
return FALSE;
}
buffer = (unsigned char *) gdMalloc (TIFFTileSize (tif));
