} else if (bps == 8) {
readTiff8bit(buffer, im, photometric, x, y, width, height, has_alpha, extra, 0);
} else if (is_bw) {
readTiffBw(buffer, im, photometric, x, y, width, height, has_alpha, extra, 0);
} else {
}
}
}
gdFree(buffer);
return TRUE;
}

