case BTIF_CORE_STORAGE_REMOTE_READ_ALL:
{
btif_storage_req_t *p_req = (btif_storage_req_t*)p_param;
btif_in_get_remote_device_properties(&p_req->read_req.bd_addr);
}break;
}
}

