return ERR_PTR(ret);
goto retry;
}
if (flags & FOLL_GET) {
get_page(page);
if (pgmap) {
put_dev_pagemap(pgmap);
pgmap = NULL;
}
}
if (flags & FOLL_TOUCH) {
if ((flags & FOLL_WRITE) &&
!pte_dirty(pte) && !PageDirty(page))
