colon = -1;
for (q = p; *q != 0x0D; ++q) {
if (*q == ':' && colon == -1) {
colon = (q - p);
}
}
if (*(q + 1) != 0x0A) {
return -1;
}
if (data + len == (q - 1) && colon == -1) {
break;
}
if (*(p + colon + 1) != 0x20) {
return -1;
