c = *sub++;
if (bytes_left)
{
if ((c & 0xc0) != 0x80)
{
complete = 1;
}
else
{
codepoint = (codepoint << 6) | (c & 0x3f);
seq_buff[index++] = c;
if (--bytes_left == 0)
{
if(codepoint > 0x10FFFF)
complete = -1;
else
{
yield = string_cat(yield, &size, &ptr, seq_buff, seq_len);
index = 0;
}
}
}
}
else
{
if((c & 0x80) == 0)
{
yield = string_cat(yield, &size, &ptr, &c, 1);
continue;
}
if((c & 0xe0) == 0xc0)
{
if(c == 0xc0 || c == 0xc1)
complete = -1;
else
{
bytes_left = 1;
codepoint = c & 0x1f;
}
}
else if((c & 0xf0) == 0xe0)
{
bytes_left = 2;
codepoint = c & 0x0f;
}
else if((c & 0xf8) == 0xf0)
{
bytes_left = 3;
codepoint = c & 0x07;
}
else
complete = -1;
seq_buff[index++] = c;
seq_len = bytes_left + 1;
}
if (complete != 0)
{
bytes_left = index = 0;
yield = string_cat(yield, &size, &ptr, UTF8_REPLACEMENT_CHAR, 1);
}
if ((complete == 1) && ((c & 0x80) == 0))
{
yield = string_cat(yield, &size, &ptr, &c, 1);
}
}
continue;
}
case EOP_ESCAPE:
{
uschar *t = string_printing(sub);
yield = string_cat(yield, &size, &ptr, t, Ustrlen(t));
continue;
}
case EOP_EVAL:
case EOP_EVAL10:
{
uschar *save_sub = sub;
