continue;
}
case EOP_STR2B64:
{
uschar *encstr = auth_b64encode(sub, Ustrlen(sub));
yield = string_cat(yield, &size, &ptr, encstr, Ustrlen(encstr));
continue;
}
case EOP_STRLEN:
{
uschar buff[24];
(void)sprintf(CS buff, "%d", Ustrlen(sub));
yield = string_cat(yield, &size, &ptr, buff, Ustrlen(buff));
continue;
}
case EOP_LENGTH:
case EOP_L:
case EOP_SUBSTR:
case EOP_S:
case EOP_HASH:
case EOP_H:
case EOP_NHASH:
case EOP_NH:
{
int sign = 1;
int value1 = 0;
int value2 = -1;
int *pn;
int len;
uschar *ret;
