visitor.visit_corrupt = visit_corrupt;
BSON_ASSERT (bson_init_static (&b, (const uint8_t *) data, sizeof data - 1));
BSON_ASSERT (bson_iter_init (&iter, &b));
BSON_ASSERT (!bson_iter_visit_all (&iter, &visitor, (void *) &visited));
BSON_ASSERT (visited);
}

