buf[offs++] = 1;
buf[offs++] = type;
buf[offs++] = IASECC_FCP_TAG_FID;
buf[offs++] = 2;
buf[offs++] = (file->id >> 8) & 0xFF;
buf[offs++] = file->id & 0xFF;
buf[offs++] = IASECC_FCP_TAG_SFID;
buf[offs++] = 0;
