if (entry->method == SC_AC_NEVER)
continue;
else if (entry->method == SC_AC_NONE)
smbs[nn_smb++] = 0x00;
else if (entry->method == SC_AC_CHV)
smbs[nn_smb++] = entry->key_ref | IASECC_SCB_METHOD_USER_AUTH;
else if (entry->method == SC_AC_SEN)
