SHA256_Update(&key->md, in + sha_off, plen - sha_off);
if (plen != len) {
if (in != out)
memcpy(out + aes_off, in + aes_off, plen - aes_off);
SHA256_Final(out + plen, &key->md);
key->md = key->tail;
SHA256_Update(&key->md, out + plen, SHA256_DIGEST_LENGTH);
SHA256_Final(out + plen, &key->md);
