FT_TRACE4(( alternate ? " hvcurveto\n" : " vhcurveto\n" ));
while ( index < count )
{
CF2_Fixed x1, x2, x3, y1, y2, y3;
if ( alternate )
{
x1 = cf2_stack_getReal( opStack, index + 0 ) + curX;
y1 = curY;
x2 = cf2_stack_getReal( opStack, index + 1 ) + x1;
y2 = cf2_stack_getReal( opStack, index + 2 ) + y1;
y3 = cf2_stack_getReal( opStack, index + 3 ) + y2;
if ( count - index == 5 )
{
x3 = cf2_stack_getReal( opStack, index + 4 ) + x2;
++index;
}
else
x3 = x2;
alternate = FALSE;
}
else
{
x1 = curX;
y1 = cf2_stack_getReal( opStack, index + 0 ) + curY;
x2 = cf2_stack_getReal( opStack, index + 1 ) + x1;
y2 = cf2_stack_getReal( opStack, index + 2 ) + y1;
x3 = cf2_stack_getReal( opStack, index + 3 ) + x2;
if ( count - index == 5 )
{
y3 = cf2_stack_getReal( opStack, index + 4 ) + y2;
++index;
}
else
y3 = y2;
alternate = TRUE;
}
cf2_glyphpath_curveTo( &glyphPath, x1, y1, x2, y2, x3, y3 );
curX   = x3;
curY   = y3;
index += 4;
}
cf2_stack_clear( opStack );
}
continue;
case cf2_cmdEXTENDEDNMBR:
{
CF2_Int  v;
v = (FT_Short)( ( cf2_buf_readByte( charstring ) << 8 ) |
cf2_buf_readByte( charstring )        );
FT_TRACE4(( " %d", v ));
cf2_stack_pushInt( opStack, v );
}
continue;
default:
{
if (   op1 <= 246 )
{
CF2_Int  v;
v = op1 - 139;
FT_TRACE4(( " %d", v ));
cf2_stack_pushInt( opStack, v );
}
else if (   op1 <= 250 )
{
CF2_Int  v;
v  = op1;
v -= 247;
v *= 256;
v += cf2_buf_readByte( charstring );
v += 108;
FT_TRACE4(( " %d", v ));
cf2_stack_pushInt( opStack, v );
}
else if (   op1 <= 254 )
{
CF2_Int  v;
v  = op1;
v -= 251;
v *= 256;
v += cf2_buf_readByte( charstring );
v  = -v - 108;
FT_TRACE4(( " %d", v ));
cf2_stack_pushInt( opStack, v );
}
else
{
CF2_Fixed  v;
v = (CF2_Fixed)
( ( (FT_UInt32)cf2_buf_readByte( charstring ) << 24 ) |
( (FT_UInt32)cf2_buf_readByte( charstring ) << 16 ) |
( (FT_UInt32)cf2_buf_readByte( charstring ) <<  8 ) |
(FT_UInt32)cf2_buf_readByte( charstring )         );
FT_TRACE4(( " %.2f", v / 65536.0 ));
cf2_stack_pushFixed( opStack, v );
}
}
continue;
}
cf2_stack_clear( opStack );
}
FT_TRACE4(( "cf2_interpT2CharString:"
"  charstring ends without ENDCHAR\n" ));
exit:
cf2_setError( error, lastError );
cf2_glyphpath_finalize( &glyphPath );
cf2_arrstack_finalize( &vStemHintArray );
cf2_arrstack_finalize( &hStemHintArray );
cf2_arrstack_finalize( &subrStack );
cf2_stack_free( opStack );
FT_TRACE4(( "\n" ));
return;
}

contrast:
cf2_interpT2CharString( CF2_Font              font,
CF2_Buffer            buf,
CF2_OutlineCallbacks  callbacks,
const FT_Vector*      translation,
FT_Bool               doingSeac,
CF2_Fixed             curX,
CF2_Fixed             curY,
CF2_Fixed*            width )
{
FT_Error  lastError = FT_Err_Ok;
CFF_Decoder*  decoder = font->decoder;
FT_Error*  error  = &font->error;
FT_Memory  memory = font->memory;
CF2_Fixed  scaleY        = font->innerTransform.d;
CF2_Fixed  nominalWidthX = cf2_getNominalWidthX( decoder );
CF2_Fixed  hintOriginY = curY;
CF2_Stack  opStack = NULL;
FT_Byte    op1;
FT_UInt32  instructionLimit = 20000000UL;
CF2_ArrStackRec  subrStack;
FT_Bool     haveWidth;
CF2_Buffer  charstring = NULL;
CF2_Int  charstringIndex = -1;
CF2_ArrStackRec  hStemHintArray;
CF2_ArrStackRec  vStemHintArray;
CF2_HintMaskRec   hintMask;
CF2_GlyphPathRec  glyphPath;
cf2_arrstack_init( &subrStack,
memory,
error,
sizeof ( CF2_BufferRec ) );
cf2_arrstack_init( &hStemHintArray,
memory,
error,
sizeof ( CF2_StemHintRec ) );
cf2_arrstack_init( &vStemHintArray,
memory,
error,
sizeof ( CF2_StemHintRec ) );
cf2_hintmask_init( &hintMask, error );
cf2_glyphpath_init( &glyphPath,
font,
callbacks,
scaleY,
&hStemHintArray,
&vStemHintArray,
&hintMask,
hintOriginY,
&font->blues,
translation );
haveWidth = FALSE;
*width    = cf2_getDefaultWidthX( decoder );
opStack = cf2_stack_init( memory, error );
if ( !opStack )
{
lastError = FT_THROW( Out_Of_Memory );
goto exit;
}
cf2_arrstack_setCount( &subrStack, CF2_MAX_SUBR + 1 );
charstring  = (CF2_Buffer)cf2_arrstack_getBuffer( &subrStack );
*charstring = *buf;
charstringIndex = 0;
if ( *error )
goto exit;
while ( 1 )
{
if ( cf2_buf_isEnd( charstring ) )
{
if ( charstringIndex )
op1 = cf2_cmdRETURN;
else
op1 = cf2_cmdENDCHAR;
}
else
op1 = (FT_Byte)cf2_buf_readByte( charstring );
if ( *error )
goto exit;
instructionLimit--;
if ( instructionLimit == 0 )
{
lastError = FT_THROW( Invalid_Glyph_Format );
goto exit;
}
switch( op1 )
{
case cf2_cmdRESERVED_0:
case cf2_cmdRESERVED_2:
case cf2_cmdRESERVED_9:
case cf2_cmdRESERVED_13:
case cf2_cmdRESERVED_15:
case cf2_cmdRESERVED_16:
case cf2_cmdRESERVED_17:
FT_TRACE4(( " unknown op (%d)\n", op1 ));
break;
case cf2_cmdHSTEMHM:
case cf2_cmdHSTEM:
FT_TRACE4(( op1 == cf2_cmdHSTEMHM ? " hstemhm\n" : " hstem\n" ));
if ( cf2_hintmask_isValid( &hintMask ) )
{
FT_TRACE4(( "cf2_interpT2CharString:"
" invalid horizontal hint mask\n" ));
break;
}
cf2_doStems( font,
opStack,
0 );
if ( font->decoder->width_only )
goto exit;
break;
case cf2_cmdVSTEMHM:
case cf2_cmdVSTEM:
FT_TRACE4(( op1 == cf2_cmdVSTEMHM ? " vstemhm\n" : " vstem\n" ));
if ( cf2_hintmask_isValid( &hintMask ) )
if ( cf2_hintmask_isValid( &hintMask ) )
{
FT_TRACE4(( "cf2_interpT2CharString:"
" invalid vertical hint mask\n" ));
break;
}
cf2_doStems( font,
opStack,
goto exit;
break;
case cf2_cmdVMOVETO:
FT_TRACE4(( " vmoveto\n" ));
if ( cf2_stack_count( opStack ) > 1 && !haveWidth )
*width = cf2_stack_getReal( opStack, 0 ) + nominalWidthX;
haveWidth = TRUE;
if ( font->decoder->width_only )
goto exit;
curY += cf2_stack_popFixed( opStack );
cf2_glyphpath_moveTo( &glyphPath, curX, curY );
break;
case cf2_cmdRLINETO:
{
CF2_UInt  index;
CF2_UInt  count = cf2_stack_count( opStack );
FT_TRACE4(( " rlineto\n" ));
for ( index = 0; index < count; index += 2 )
{
curX += cf2_stack_getReal( opStack, index + 0 );
curY += cf2_stack_getReal( opStack, index + 1 );
cf2_glyphpath_lineTo( &glyphPath, curX, curY );
}
cf2_stack_clear( opStack );
}
continue;
case cf2_cmdHLINETO:
case cf2_cmdVLINETO:
{
CF2_UInt  index;
CF2_UInt  count = cf2_stack_count( opStack );
FT_Bool  isX = op1 == cf2_cmdHLINETO;
FT_TRACE4(( isX ? " hlineto\n" : " vlineto\n" ));
for ( index = 0; index < count; index++ )
{
CF2_Fixed  v = cf2_stack_getReal( opStack, index );
if ( isX )
curX += v;
else
curY += v;
isX = !isX;
cf2_glyphpath_lineTo( &glyphPath, curX, curY );
}
cf2_stack_clear( opStack );
}
continue;
case cf2_cmdRCURVELINE:
case cf2_cmdRRCURVETO:
{
CF2_UInt  count = cf2_stack_count( opStack );
CF2_UInt  index = 0;
FT_TRACE4(( op1 == cf2_cmdRCURVELINE ? " rcurveline\n"
: " rrcurveto\n" ));
while ( index + 6 <= count )
{
CF2_Fixed  x1 = cf2_stack_getReal( opStack, index + 0 ) + curX;
CF2_Fixed  y1 = cf2_stack_getReal( opStack, index + 1 ) + curY;
CF2_Fixed  x2 = cf2_stack_getReal( opStack, index + 2 ) + x1;
CF2_Fixed  y2 = cf2_stack_getReal( opStack, index + 3 ) + y1;
CF2_Fixed  x3 = cf2_stack_getReal( opStack, index + 4 ) + x2;
CF2_Fixed  y3 = cf2_stack_getReal( opStack, index + 5 ) + y2;
cf2_glyphpath_curveTo( &glyphPath, x1, y1, x2, y2, x3, y3 );
curX   = x3;
curY   = y3;
index += 6;
}
if ( op1 == cf2_cmdRCURVELINE )
{
curX += cf2_stack_getReal( opStack, index + 0 );
curY += cf2_stack_getReal( opStack, index + 1 );
cf2_glyphpath_lineTo( &glyphPath, curX, curY );
}
cf2_stack_clear( opStack );
}
continue;
case cf2_cmdCALLGSUBR:
case cf2_cmdCALLSUBR:
{
CF2_UInt  subrIndex;
FT_TRACE4(( op1 == cf2_cmdCALLGSUBR ? " callgsubr"
: " callsubr" ));
if ( charstringIndex > CF2_MAX_SUBR )
{
lastError = FT_THROW( Invalid_Glyph_Format );
goto exit;
}
charstring = (CF2_Buffer)
cf2_arrstack_getPointer( &subrStack,
charstringIndex + 1 );
subrIndex = cf2_stack_popInt( opStack );
switch ( op1 )
{
case cf2_cmdCALLGSUBR:
FT_TRACE4(( "(%d)\n", subrIndex + decoder->globals_bias ));
if ( cf2_initGlobalRegionBuffer( decoder,
subrIndex,
charstring ) )
{
lastError = FT_THROW( Invalid_Glyph_Format );
goto exit;
}
break;
default:
FT_TRACE4(( "(%d)\n", subrIndex + decoder->locals_bias ));
if ( cf2_initLocalRegionBuffer( decoder,
subrIndex,
charstring ) )
{
lastError = FT_THROW( Invalid_Glyph_Format );
goto exit;
}
}
charstringIndex += 1;
}
continue;
case cf2_cmdRETURN:
FT_TRACE4(( " return\n" ));
if ( charstringIndex < 1 )
{
lastError = FT_THROW( Invalid_Glyph_Format );
goto exit;
}
charstring = (CF2_Buffer)
cf2_arrstack_getPointer( &subrStack,
--charstringIndex );
continue;
case cf2_cmdESC:
{
FT_Byte  op2 = (FT_Byte)cf2_buf_readByte( charstring );
switch ( op2 )
{
case cf2_escDOTSECTION:
FT_TRACE4(( " dotsection\n" ));
break;
case cf2_escAND:
FT_TRACE4(( " and\n" ));
CF2_FIXME;
break;
case cf2_escOR:
FT_TRACE4(( " or\n" ));
CF2_FIXME;
break;
case cf2_escNOT:
FT_TRACE4(( " not\n" ));
CF2_FIXME;
break;
case cf2_escABS:
FT_TRACE4(( " abs\n" ));
CF2_FIXME;
break;
case cf2_escADD:
FT_TRACE4(( " add\n" ));
CF2_FIXME;
break;
case cf2_escSUB:
FT_TRACE4(( " sub\n" ));
CF2_FIXME;
break;
case cf2_escDIV:
FT_TRACE4(( " div\n" ));
CF2_FIXME;
break;
case cf2_escNEG:
FT_TRACE4(( " neg\n" ));
CF2_FIXME;
break;
case cf2_escEQ:
FT_TRACE4(( " eq\n" ));
CF2_FIXME;
break;
case cf2_escDROP:
FT_TRACE4(( " drop\n" ));
CF2_FIXME;
break;
case cf2_escPUT:
FT_TRACE4(( " put\n" ));
CF2_FIXME;
break;
case cf2_escGET:
FT_TRACE4(( " get\n" ));
CF2_FIXME;
break;
case cf2_escIFELSE:
FT_TRACE4(( " ifelse\n" ));
CF2_FIXME;
break;
case cf2_escRANDOM:
FT_TRACE4(( " random\n" ));
CF2_FIXME;
break;
case cf2_escMUL:
FT_TRACE4(( " mul\n" ));
