if (ch + length < chend) {
list[i] = ch+1;
ch += length + 1;
length = *ch;
*ch = '\0';
count++;
} else
list[i] = NULL;
}
}
*nextensions = count;
UnlockDisplay(dpy);
SyncHandle();
return (list);
}

