static int _hid_get_descriptor(struct hid_device_priv* dev, HANDLE hid_handle, int recipient,
int type, int _index, void *data, size_t *size)
{
switch(type) {
case LIBUSB_DT_DEVICE:
usbi_dbg("LIBUSB_DT_DEVICE");
