le16_to_cpu(status_rid.SSIDlen),
status_rid.SSID,
status_rid.apName,
le16_to_cpu(status_rid.channel),
le16_to_cpu(status_rid.currentXmitRate) / 2,
version,
cap_rid.prodName,
