}
if (!p) {
ALOGE("packet_put_tail_l: unable to allocate packet...");
return FALSE;
}
p->next = NULL;
p->prev = sock->last_packet;
sock->last_packet = p;
if (p->prev)
p->prev->next = p;
else
sock->first_packet = p;
sock->bytes_buffered += len;
return TRUE;
}

