RCHECK(visual_object_verid > 0 && visual_object_verid < 3);
RCHECK(ReadBits(&reader, 3) != 0);
}
int visual_object_type = ReadBits(&reader, 4);
RCHECK(visual_object_type > 0 && visual_object_type < 6);
break;
}
case VOP_START_CODE:
