int fpm_stdio_init_child(struct fpm_worker_pool_s *wp)
{
#ifdef HAVE_SYSLOG_H
if (fpm_globals.error_log_fd == ZLOG_SYSLOG) {
closelog();
} else
#endif
if (fpm_globals.error_log_fd > 0) {
close(fpm_globals.error_log_fd);
}
