uh->check = 0;
if (is_udplite)
csum = udplite_csum(skb);
else if (sk->sk_no_check_tx) {
skb->ip_summed = CHECKSUM_NONE;
goto send;
} else if (skb->ip_summed == CHECKSUM_PARTIAL) {
udp4_hwcsum(skb, fl4->saddr, fl4->daddr);
