(npages != old.npages) ||
((new.flags ^ old.flags) & KVM_MEM_READONLY))
goto out;
if (base_gfn != old.base_gfn)
change = KVM_MR_MOVE;
else if (new.flags != old.flags)
change = KVM_MR_FLAGS_ONLY;
else {
r = 0;
goto out;
}
}
} else if (old.npages) {
change = KVM_MR_DELETE;
} else
goto out;
