if((u1_picture_type & 0x03) == FRM_PIC)
{
ps_dpb_info[i].u1_used_as_ref = IS_SHORT_TERM;
ps_dpb_info[i].s_top_field.u1_reference_info = IS_SHORT_TERM;
ps_dpb_info[i].s_bot_field.u1_reference_info = IS_SHORT_TERM;
}
