fwi == 0 ? "[" : " ", fw[0], fwi == 0 ? "]" : " ",
fwi == 1 ? "[" : " ", fw[1], fwi == 1 ? "]" : " ",
fwi == 2 ? "[" : " ", fw[2], fwi == 2 ? "]" : " ",
fwi == 3 ? "[" : " ", fw[3], fwi == 3 ? "]" : " ",
