ps_parser_to_token( PS_Parser  parser,
T1_Token   token )
{
FT_Byte*  cur;
FT_Byte*  limit;
FT_Int    embed;
token->type  = T1_TOKEN_TYPE_NONE;
token->start = NULL;
token->limit = NULL;
ps_parser_skip_spaces( parser );
cur   = parser->cursor;
limit = parser->limit;
if ( cur >= limit )
return;
switch ( *cur )
{
case '(':
token->type  = T1_TOKEN_TYPE_STRING;
token->start = cur;
if ( skip_literal_string( &cur, limit ) == FT_Err_Ok )
token->limit = cur;
break;
case '{':
token->type  = T1_TOKEN_TYPE_ARRAY;
token->start = cur;
if ( skip_procedure( &cur, limit ) == FT_Err_Ok )
token->limit = cur;
break;
case '[':
token->type  = T1_TOKEN_TYPE_ARRAY;
embed        = 1;
token->start = cur++;
parser->cursor = cur;
ps_parser_skip_spaces( parser );
cur = parser->cursor;
while ( cur < limit && !parser->error )
{
if ( *cur == '[' )
embed++;
else if ( *cur == ']' )
{
embed--;
if ( embed <= 0 )
{
token->limit = ++cur;
break;
}
}
parser->cursor = cur;
ps_parser_skip_PS_token( parser );
ps_parser_skip_spaces  ( parser );
cur = parser->cursor;
}
break;
default:
token->start = cur;
token->type  = ( *cur == '/' ) ? T1_TOKEN_TYPE_KEY : T1_TOKEN_TYPE_ANY;
ps_parser_skip_PS_token( parser );
cur = parser->cursor;
if ( !parser->error )
token->limit = cur;
}
if ( !token->limit )
{
token->start = NULL;
token->type  = T1_TOKEN_TYPE_NONE;
}
parser->cursor = cur;
}
FT_LOCAL_DEF( void )
ps_parser_to_token_array( PS_Parser  parser,
T1_Token   tokens,
FT_UInt    max_tokens,
FT_Int*    pnum_tokens )
{
T1_TokenRec  master;
*pnum_tokens = -1;
ps_parser_to_token( parser, &master );
if ( master.type == T1_TOKEN_TYPE_ARRAY )
{
FT_Byte*  old_cursor = parser->cursor;
FT_Byte*  old_limit  = parser->limit;
T1_Token  cur        = tokens;
T1_Token  limit      = cur + max_tokens;
parser->cursor = master.start + 1;
parser->limit  = master.limit - 1;
while ( parser->cursor < parser->limit )
{
T1_TokenRec  token;
ps_parser_to_token( parser, &token );
if ( !token.type )
break;
if ( tokens && cur < limit )
*cur = token;
cur++;
}
*pnum_tokens = (FT_Int)( cur - tokens );
parser->cursor = old_cursor;
parser->limit  = old_limit;
}
}
static FT_Int
ps_tocoordarray( FT_Byte*  *acur,
FT_Byte*   limit,
FT_Int     max_coords,
FT_Short*  coords )
{
FT_Byte*  cur   = *acur;
FT_Int    count = 0;
FT_Byte   c, ender;
if ( cur >= limit )
goto Exit;
c     = *cur;
ender = 0;
if ( c == '[' )
ender = ']';
else if ( c == '{' )
ender = '}';
if ( ender )
cur++;
while ( cur < limit )
{
FT_Short  dummy;
FT_Byte*  old_cur;
skip_spaces( &cur, limit );
if ( cur >= limit )
goto Exit;
if ( *cur == ender )
{
cur++;
break;
}
old_cur = cur;
if ( coords && count >= max_coords )
break;
*( coords ? &coords[count] : &dummy ) =
(FT_Short)( PS_Conv_ToFixed( &cur, limit, 0 ) >> 16 );
if ( old_cur == cur )
{
count = -1;
goto Exit;
}
else
count++;
if ( !ender )
break;
}
Exit:
*acur = cur;
return count;
}
