FT_Int    b )
{
FT_Int32   sign;
FT_UInt32  ah, al, mid, lo, hi;
sign = a ^ b;
if ( a < 0 )
a = -a;
if ( b < 0 )
b = -b;
ah = (FT_UInt32)( ( a >> 16 ) & 0xFFFFU );
al = (FT_UInt32)( a & 0xFFFFU );
lo    = al * b;
mid   = ah * b;
hi    = mid >> 16;
mid   = ( mid << 16 ) + ( 1 << 13 );
lo   += mid;
if ( lo < mid )
hi += 1;
mid = ( lo >> 14 ) | ( hi << 18 );
return sign >= 0 ? (FT_Int32)mid : -(FT_Int32)mid;
}

