IsMacBinary( FT_Library  library,
FT_Stream   stream,
FT_Long     face_index,
FT_Face    *aface )
{
unsigned char  header[128];
FT_Error       error;
FT_Long        dlen, offset;
if ( NULL == stream )
return FT_Err_Invalid_Stream_Operation;
error = FT_Stream_Seek( stream, 0 );
if ( error )
goto Exit;
error = FT_Stream_Read( stream, (FT_Byte*)header, 128 );
if ( error )
goto Exit;
if (            header[ 0] !=  0 ||
header[74] !=  0 ||
header[82] !=  0 ||
header[ 1] ==  0 ||
header[ 1] >  33 ||
header[63] !=  0 ||
header[2 + header[1]] !=  0 )
return FT_Err_Unknown_File_Format;
dlen = ( header[0x53] << 24 ) |
( header[0x54] << 16 ) |
( header[0x55] <<  8 ) |
header[0x56];
#if 0
rlen = ( header[0x57] << 24 ) |
( header[0x58] << 16 ) |
( header[0x59] <<  8 ) |
header[0x5a];
#endif
offset = 128 + ( ( dlen + 127 ) & ~127 );
return IsMacResource( library, stream, offset, face_index, aface );
Exit:
return error;
}

